<?php require 'config/db.php';require 'includes/functions.php';require_role('admin');
$counts=[];foreach(['users'=>'SELECT COUNT(*) c FROM users','donors'=>'SELECT COUNT(*) c FROM donor_profiles','active'=>"SELECT COUNT(*) c FROM blood_requests WHERE status NOT IN ('completed','cancelled')",'completed'=>"SELECT COUNT(*) c FROM blood_requests WHERE status='completed'",'history'=>'SELECT COUNT(*) c FROM case_history'] as $k=>$sql)$counts[$k]=(int)$conn->query($sql)->fetch_assoc()['c'];
$reqs=$conn->query("SELECT br.*,h.name hospital_name,(SELECT COUNT(*) FROM request_matches rm WHERE rm.request_id=br.id) matches FROM blood_requests br LEFT JOIN hospitals h ON h.id=br.hospital_id ORDER BY br.created_at DESC LIMIT 10");$logs=$conn->query("SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 10");$stocks=$conn->query("SELECT bs.*,h.name hospital_name FROM blood_stock bs JOIN hospitals h ON h.id=bs.hospital_id ORDER BY (bs.units<bs.min_threshold) DESC,bs.units ASC LIMIT 8");$pageTitle='Admin Command Center';include 'includes/header.php';?>
<section class="dashboard"><div class="container"><div class="dashboard-head"><div><span class="kicker">Emergency operations</span><h1>Admin command center</h1><p>Control live cases, website content, blood stock and complete network history.</p></div><div class="admin-actions"><a class="btn btn-ghost" href="admin-content.php"><i class="fa-solid fa-photo-film"></i> Website content</a><a class="btn btn-ghost" href="history.php"><i class="fa-solid fa-clock-rotate-left"></i> Full history</a><a class="btn btn-primary" href="request-blood.php">+ New emergency</a></div></div>
<div class="metric-grid"><div class="metric"><div class="icon"><i class="fa-solid fa-users"></i></div><strong><?=$counts['users']?></strong><span>Total users</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-droplet"></i></div><strong><?=$counts['donors']?></strong><span>Donors</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-bolt"></i></div><strong><?=$counts['active']?></strong><span>Active cases</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-clock-rotate-left"></i></div><strong><?=$counts['history']?></strong><span>History events</span></div></div>
<div class="command-overview"><div class="panel wide"><div class="panel-title"><h3>Live emergency board</h3><a href="requests.php">View all →</a></div><div class="table-wrap"><table class="table"><tr><th>Case</th><th>Patient / hospital</th><th>Blood</th><th>Priority</th><th>Matches</th><th>Status</th><th></th></tr><?php while($r=$reqs->fetch_assoc()):?><tr><td>#<?=str_pad($r['id'],5,'0',STR_PAD_LEFT)?></td><td><b><?=e($r['patient_name'])?></b><br><small><?=e($r['hospital_name']?:$r['address'])?></small></td><td><span class="blood-pill"><?=e($r['blood_group'])?></span></td><td><span class="priority <?=e($r['priority'])?>"><?=e($r['priority'])?></span></td><td><?=$r['matches']?></td><td><?=e(status_label($r['status']))?></td><td><a class="btn btn-sm btn-ghost" href="request-view.php?id=<?=$r['id']?>">Open</a></td></tr><?php endwhile;?></table></div></div>
<div class="panel"><h3>Low stock watch</h3><?php while($s=$stocks->fetch_assoc()):?><div class="stock-row <?=$s['units']<$s['min_threshold']?'danger':''?>"><div class="history-blood"><?=e($s['blood_group'])?></div><div><b><?=$s['units']?> units</b><span><?=e($s['hospital_name'])?></span></div><small>Min <?=$s['min_threshold']?></small></div><?php endwhile;?></div></div>
<div class="dash-grid" style="margin-top:20px"><div class="panel"><h3>Operational modules</h3><div class="module-grid"><a href="admin-content.php"><i class="fa-solid fa-images"></i><b>Dynamic media & homepage</b><span>Change slides, video and public content</span></a><a href="history.php"><i class="fa-solid fa-timeline"></i><b>Case history</b><span>Trace every request and status journey</span></a><a href="requests.php"><i class="fa-solid fa-tower-broadcast"></i><b>Emergency requests</b><span>Open and manage active cases</span></a><a href="profile.php"><i class="fa-solid fa-shield-halved"></i><b>Account & security</b><span>Role-based protected admin access</span></a></div></div><div class="panel"><h3>Recent audit activity</h3><?php while($l=$logs->fetch_assoc()):?><div class="notification"><div class="n-icon"><i class="fa-solid fa-clock-rotate-left"></i></div><div><b><?=e($l['action'])?></b><span><?=e($l['name']?:'System')?> • <?=date('M d, H:i',strtotime($l['created_at']))?></span></div></div><?php endwhile;?></div></div></div></section><?php include 'includes/footer.php';?>
